def bucket_sort_into_ranges(nums, boundaries):
    k = len(boundaries) - 1
    result = []
    for i in range(k):
        lo, hi = boundaries[i], boundaries[i + 1]
        if i == k - 1:
            bucket = [v for v in nums if lo <= v <= hi]
        else:
            bucket = [v for v in nums if lo <= v < hi]
        result.append(sorted(bucket))
    return result

