def is_valid_luhn_number(s):
    if len(s) < 2 or not s.isdigit():
        return False
    def transform(pos_val):
        pos, val = pos_val
        if pos % 2 == 0:
            return val
        doubled = val * 2
        return doubled - 9 if doubled > 9 else doubled
    total = sum(transform(pv) for pv in enumerate(int(c) for c in reversed(s)))
    return total % 10 == 0

