import functools

def stable_sort_indices_descending(nums):
    def compare(i, j):
        if nums[i] != nums[j]:
            return -1 if nums[i] > nums[j] else 1
        return -1 if i < j else 1
    return sorted(range(len(nums)), key=functools.cmp_to_key(compare))

